import sys
from collections import deque

sys.setrecursionlimit(1 << 20)


class Dinic:
    def __init__(self, n):
        self.n = n
        self.g = [[] for _ in range(n)]
        self.level = [-1] * n
        self.it = [0] * n

    def add_edge(self, fr, to, cap):
        self.g[fr].append([to, cap, len(self.g[to])])
        self.g[to].append([fr, 0, len(self.g[fr]) - 1])

    def bfs(self, s, t):
        self.level = [-1] * self.n
        self.level[s] = 0
        q = deque([s])

        while q:
            v = q.popleft()
            for to, cap, rev in self.g[v]:
                if cap > 0 and self.level[to] < 0:
                    self.level[to] = self.level[v] + 1
                    q.append(to)

        return self.level[t] >= 0

    def dfs(self, v, t, f):
        if v == t:
            return f

        while self.it[v] < len(self.g[v]):
            e = self.g[v][self.it[v]]
            to, cap, rev = e

            if cap > 0 and self.level[to] == self.level[v] + 1:
                ret = self.dfs(to, t, min(f, cap))
                if ret > 0:
                    e[1] -= ret
                    self.g[to][rev][1] += ret
                    return ret

            self.it[v] += 1

        return 0

    def max_flow(self, s, t):
        flow = 0
        INF_FLOW = 10**18

        while self.bfs(s, t):
            self.it = [0] * self.n
            while True:
                f = self.dfs(s, t, INF_FLOW)
                if f == 0:
                    break
                flow += f

        return flow


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    it = iter(data)
    N = next(it)
    M = next(it)
    K = next(it)

    edges = []
    for _ in range(M):
        u = next(it) - 1
        v = next(it) - 1
        edges.append((u, v))

    INF = 10**8
    answer = 0

    for t in range(1, N):
        node_count = N * t
        S = node_count
        T = node_count + 1
        dinic = Dinic(node_count + 2)

        def node(v, level):
            return v * t + (level - 1)

        # Cost: for each original edge u -> v and each level l,
        # pay 1 if x[v][l] = 1 and x[u][l] = 0.
        for u, v in edges:
            for l in range(1, t + 1):
                dinic.add_edge(node(v, l), node(u, l), 1)

        # Monotonicity: x[v][l+1] <= x[v][l]
        for v in range(N):
            for l in range(1, t):
                dinic.add_edge(node(v, l + 1), node(v, l), INF)

        # Constraint p[v] <= p[u] + 1 for every edge u -> v:
        # x[v][l] = 1 implies x[u][l-1] = 1 for l >= 2.
        for u, v in edges:
            for l in range(2, t + 1):
                dinic.add_edge(node(v, l), node(u, l - 1), INF)

        # Fix p[0] = 0, so x[0][l] = 0 for all l.
        for l in range(1, t + 1):
            dinic.add_edge(node(0, l), T, INF)

        # Fix p[N-1] = t, so x[N-1][l] = 1 for all l.
        for l in range(1, t + 1):
            dinic.add_edge(S, node(N - 1, l), INF)

        min_edges_needed = dinic.max_flow(S, T)

        if min_edges_needed <= K:
            answer = t
        else:
            break

    print(answer)


if __name__ == "__main__":
    solve()
