def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, M, A, B = data[0], data[1], data[2], data[3]

    intervals = []
    idx = 4
    for _ in range(M):
        intervals.append((data[idx], data[idx + 1]))
        idx += 2

    # If every move has the same length, the path is uniquely determined.
    if A == B:
        if (N - 1) % A != 0:
            print("No")
            return

        for L, R in intervals:
            rem = (1 - L) % A
            if L + rem <= R:
                print("No")
                return

        print("Yes")
        return

    FULL = (1 << B) - 1

    source_mask = 0
    for d in range(A - 1, B):
        source_mask |= 1 << d

    # After processing square 1.
    mask = 1
    p = 1

    LIMIT = B * B + B + 5

    def advance_good(length):
        nonlocal mask
        if length <= 0:
            return

        if length <= LIMIT:
            for _ in range(length):
                bit = 1 if (mask & source_mask) else 0
                mask = ((mask << 1) & FULL) | bit
        else:
            for _ in range(LIMIT):
                bit = 1 if (mask & source_mask) else 0
                mask = ((mask << 1) & FULL) | bit

            if mask != 0:
                mask = FULL
            else:
                mask = 0

    def advance_bad(length):
        nonlocal mask
        if length <= 0:
            return

        k = length if length < B else B
        mask = (mask << k) & FULL

    for L, R in intervals:
        good_len = L - p - 1
        if good_len > 0:
            advance_good(good_len)

        p = L - 1

        bad_len = R - L + 1
        advance_bad(bad_len)

        p = R

    good_len = N - p
    if good_len > 0:
        advance_good(good_len)

    if mask & 1:
        print("Yes")
    else:
        print("No")


